const { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, rmSync } = await import("fs");
const { tmpdir } = await import("os");
const { join } = await import("path");
const { execFileSync } = await import("child_process");
const { pathToFileURL } = await import("url");
const repo = mkdtempSync(join(tmpdir(), "koala-done-"));
const git = (...args) => execFileSync("git", args, { cwd: repo, encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] });
git("init", "-b", "main");
git("config", "user.email", "fixture@example.com");
git("config", "user.name", "fixture");
writeFileSync(join(repo, "README.md"), "base\n");
git("add", "."); git("commit", "-m", "base");
git("checkout", "-b", "story/B-test");
mkdirSync(join(repo, "docs/story/actives/B-test"), { recursive: true });
writeFileSync(join(repo, "docs/story/actives/B-test/index.json"), JSON.stringify({ storyId: "B-test", phase: "TEST", title: "canonical" }, null, 2) + "\n");
writeFileSync(join(repo, "docs/story/actives/B-test/checklist.json"), JSON.stringify({ items: [{ id: "CHK-001", status: "done" }] }, null, 2) + "\n");
git("add", "docs/story/actives/B-test"); git("commit", "-m", "story meta");
git("checkout", "main");
try {
  mkdirSync(join(repo, "docs/story/actives/B-test"), { recursive: true });
  writeFileSync(join(repo, "docs/story/actives/B-test/index.json"), JSON.stringify({ storyId: "B-test", phase: "INIT_CHECK" }) + "\n");
  const mod = await import(pathToFileURL($root + "/packages/main/dist/handlers/story-advance.js").href);
  const pre = mod.inspectDoneMainMergePreflight({ branch: "story/B-test", storyId: "B-test", mainRepoRoot: repo, wtPathAbs: repo, commitMessage: "c", mergeMessage: "m" });
  const backup = mod.backupDoneMainResidue({ branch: "story/B-test", storyId: "B-test", mainRepoRoot: repo, wtPathAbs: repo, commitMessage: "c", mergeMessage: "m" }, pre);
  return { auto: pre.autoBackupDir, blocking: pre.blockingPaths.length, removed: !existsSync(join(repo, "docs/story/actives/B-test")), backed: Boolean(backup && existsSync(backup)) };
} finally { rmSync(repo, { recursive: true, force: true }); }

