const name = "terminal-residue-" + Date.now();
const created = await $handlers.story_create({ name, title: "Terminal residue", description: "fixture", type: "bug", priority: "low", forceNew: true });
const storyId = created.match(/B-[a-f0-9]+/)[0];
await $handlers.story_discard({ storyId, confirm: true, reason: "fixture setup" });
const out = await $handlers.story_reconcile({ dryRun: true });
await $handlers.story_discard({ storyId, cleanupResidue: true, confirm: true });
return { listed: out.includes(storyId) && out.includes("safe-untracked") };

const name = "active-residue-" + Date.now();
const created = await $handlers.story_create({ name, title: "Active residue", description: "fixture", type: "bug", priority: "low", forceNew: true });
const storyId = created.match(/B-[a-f0-9]+/)[0];
const out = await $handlers.story_reconcile({ dryRun: false });
const stillReadable = await $handlers.story_get({ storyId });
await $handlers.story_discard({ storyId, cleanupResidue: true, confirm: true });
return { notListed: !out.includes(storyId), phase: stillReadable.story.phase };

const { mkdirSync, writeFileSync, rmSync } = await import("fs");
const { execFileSync } = await import("child_process");
const storyId = "B-track" + Date.now().toString(16).slice(-2);
const dir = $root + "/docs/story/actives/" + storyId;
mkdirSync(dir, { recursive: true });
writeFileSync(dir + "/index.json", JSON.stringify({ storyId, name: "tracked", title: "Tracked", type: "bug", priority: "low", phase: "DISCARDED" }) + "\n");
writeFileSync(dir + "/checklist.json", JSON.stringify({ items: [] }) + "\n");
execFileSync("git", ["add", "docs/story/actives/" + storyId + "/index.json"], { cwd: $root });
try {
  const out = await $handlers.story_reconcile({ dryRun: true });
  execFileSync("git", ["reset", "--", "docs/story/actives/" + storyId + "/index.json"], { cwd: $root });
  rmSync(dir, { recursive: true, force: true });
  return { unsafe: out.includes(storyId) && out.includes("unsafe") };
} catch (e) {
  execFileSync("git", ["reset", "--", "docs/story/actives/" + storyId + "/index.json"], { cwd: $root });
  rmSync(dir, { recursive: true, force: true });
  throw e;
}

